func TestStorage_GetEventsAfter_And_Ack(t *testing.T) {
	dbPath := "test_replay_ack.db"
	defer os.Remove(dbPath)
	defer os.Remove(dbPath + "-wal")
	defer os.Remove(dbPath + "-shm")

	s, err := New(dbPath)
	if err != nil {
		t.Fatalf("failed to initialize storage: %v", err)
	}
	defer s.Close()

	ctx := context.Background()
	evt1, _ := s.InsertEvent(ctx, "chan_x", "webhook", `{}`, []byte(`{"order":1}`))
	evt2, _ := s.InsertEvent(ctx, "chan_x", "webhook", `{}`, []byte(`{"order":2}`))
	evt3, _ := s.InsertEvent(ctx, "chan_x", "webhook", `{}`, []byte(`{"order":3}`))

	// Replay events after evt1 -> should return evt2 and evt3
	missed, err := s.GetEventsAfter(ctx, "chan_x", evt1.ID, 10)
	if err != nil {
		t.Fatalf("failed to get events after %s: %v", evt1.ID, err)
	}
	if len(missed) != 2 {
		t.Fatalf("expected 2 missed events, got %d", len(missed))
	}
	if missed[0].ID != evt2.ID || missed[1].ID != evt3.ID {
		t.Errorf("expected [evt2, evt3], got [%s, %s]", missed[0].ID, missed[1].ID)
	}

	// Ack evt2
	if err := s.AckEvent(ctx, evt2.ID); err != nil {
		t.Fatalf("failed to ack evt2: %v", err)
	}

	// Verify status in DB
	var status string
	err = s.readDB.QueryRow("SELECT status FROM events WHERE id = ?", evt2.ID).Scan(&status)
	if err != nil {
		t.Fatalf("failed to query status: %v", err)
	}
	if status != "acked" {
		t.Errorf("expected status 'acked', got %q", status)
	}
}

func TestStorage_PruneEvents(t *testing.T) {
	dbPath := "test_prune.db"
	defer os.Remove(dbPath)
	defer os.Remove(dbPath + "-wal")
	defer os.Remove(dbPath + "-shm")

	s, err := New(dbPath)
	if err != nil {
		t.Fatalf("failed to initialize storage: %v", err)
	}
	defer s.Close()

	ctx := context.Background()

	evtRecentPending, err := s.InsertEvent(ctx, "chan_prune", "webhook", `{}`, []byte(`{"recent":true}`))
	if err != nil {
		t.Fatalf("failed to insert event: %v", err)
	}
	evtRecentAcked, err := s.InsertEvent(ctx, "chan_prune", "webhook", `{}`, []byte(`{"recent_acked":true}`))
	if err != nil {
		t.Fatalf("failed to insert event: %v", err)
	}
	evtOldAcked, err := s.InsertEvent(ctx, "chan_prune", "webhook", `{}`, []byte(`{"old_acked":true}`))
	if err != nil {
		t.Fatalf("failed to insert event: %v", err)
	}
	evtOldUnacked, err := s.InsertEvent(ctx, "chan_prune", "webhook", `{}`, []byte(`{"old_unacked":true}`))
	if err != nil {
		t.Fatalf("failed to insert event: %v", err)
	}

	_ = s.AckEvent(ctx, evtRecentAcked.ID)
	_ = s.AckEvent(ctx, evtOldAcked.ID)

	oldAckedDate := time.Now().Add(-48 * time.Hour).UTC().Format("2006-01-02 15:04:05")
	_, err = s.writeDB.Exec("UPDATE events SET created_at = ?, acked_at = ? WHERE id = ?", oldAckedDate, oldAckedDate, evtOldAcked.ID)
	if err != nil {
		t.Fatalf("failed to backdate old acked event: %v", err)
	}

	oldUnackedDate := time.Now().Add(-10 * 24 * time.Hour).UTC().Format("2006-01-02 15:04:05")
	_, err = s.writeDB.Exec("UPDATE events SET created_at = ? WHERE id = ?", oldUnackedDate, evtOldUnacked.ID)
	if err != nil {
		t.Fatalf("failed to backdate old unacked event: %v", err)
	}

	ackedCutoff := time.Now().Add(-24 * time.Hour)
	unackedCutoff := time.Now().Add(-7 * 24 * time.Hour)

	deleted, err := s.PruneEvents(ctx, ackedCutoff, unackedCutoff)
	if err != nil {
		t.Fatalf("PruneEvents returned error: %v", err)
	}
	if deleted != 2 {
		t.Errorf("expected 2 pruned events, got %d", deleted)
	}

	remaining, err := s.ListEvents(ctx, "chan_prune", 10)
	if err != nil {
		t.Fatalf("ListEvents failed: %v", err)
	}
	if len(remaining) != 2 {
		t.Fatalf("expected 2 remaining events, got %d", len(remaining))
	}

	remainingIDs := map[string]bool{remaining[0].ID: true, remaining[1].ID: true}
	if !remainingIDs[evtRecentPending.ID] || !remainingIDs[evtRecentAcked.ID] {
		t.Errorf("expected recent events to remain in storage")
	}
}

func TestStorage_GroupCommitBatching(t *testing.T) {
	dbPath := "test_batching.db"
	defer os.Remove(dbPath)
	defer os.Remove(dbPath + "-wal")
	defer os.Remove(dbPath + "-shm")

	s, err := New(dbPath)
	if err != nil {
		t.Fatalf("failed to initialize storage: %v", err)
	}
	defer s.Close()

	ctx := context.Background()
	totalEvents := 120
	var wg sync.WaitGroup

	errCh := make(chan error, totalEvents)
	for i := 0; i < totalEvents; i++ {
		wg.Add(1)
		go func(idx int) {
			defer wg.Done()
			_, err := s.InsertEvent(ctx, "chan_batch", "webhook", `{"batch":"true"}`, []byte(`{"idx":1}`))
			if err != nil {
				errCh <- err
			}
		}(i)
	}

	wg.Wait()
	close(errCh)

	for err := range errCh {
		t.Fatalf("unexpected insert error in batching: %v", err)
	}

	var count int
	if err := s.readDB.QueryRow("SELECT COUNT(*) FROM events WHERE channel_id = 'chan_batch'").Scan(&count); err != nil {
		t.Fatalf("failed to count events: %v", err)
	}

	if count != totalEvents {
		t.Fatalf("expected %d events, got %d", totalEvents, count)
	}
}

func TestStorage_ConcurrentReadWrite(t *testing.T) {
	dbPath := "test_concurrent_rw.db"
	defer os.Remove(dbPath)
	defer os.Remove(dbPath + "-wal")
	defer os.Remove(dbPath + "-shm")

	s, err := New(dbPath)
	if err != nil {
		t.Fatalf("failed to initialize storage: %v", err)
	}
	defer s.Close()

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	var wg sync.WaitGroup

	// Concurrently insert events
	for i := 0; i < 5; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				default:
					_, _ = s.InsertEvent(ctx, "chan_rw", "webhook", `{}`, []byte(`{"hello":"world"}`))
					time.Sleep(5 * time.Millisecond)
				}
			}
		}()
	}

	// Concurrently read events using read pool
	for i := 0; i < 5; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				default:
					_, err := s.ListEvents(ctx, "chan_rw", 20)
					if err != nil && ctx.Err() == nil {
						t.Errorf("read error: %v", err)
						return
					}
					time.Sleep(5 * time.Millisecond)
				}
			}
		}()
	}

	wg.Wait()
}
